import { useEffect, useRef } from 'react';
import { useAuth } from '@/context/AuthContext';

/**
 * Optional AGENT customer support for johna-s.
 *
 * The public widget key is generated by AGENT for this PROJECT + the
 * https://premieros.github.io origin. No Supabase credentials are shared
 * with AGENT. Each project uses its own key and server-side knowledge base.
 *
 * The dedicated Johna-S project and public key are configured. The deployment
 * remains gated by GitHub's verified-main workflow.
 */
const SUPPORT_ORIGIN = 'https://premieros-agent-support-public.vercel.app';
// The public widget key belongs only to Johna-S, never to Premier.
const PUBLIC_KEY = '8e299da0ef520017d2c74c4e688109dd0dda3b48cee20f2d';
const KEY_FORMAT = /^[a-f0-9]{48}$/;

export function AgentCustomerSupport() {
  const { user, loading } = useAuth();
  const lastUserId = useRef<string | null>(null);

  useEffect(() => {
    // No second login. The support widget is shown only after the existing
    // johna-s login has finished and only with Johna-S's own public key.
    if (loading || !user?.id || !KEY_FORMAT.test(PUBLIC_KEY)) return;

    const userKey = 'johna-s:agent-support-user:' + PUBLIC_KEY;
    const conversationKey = 'support-ai:' + SUPPORT_ORIGIN + ':' + PUBLIC_KEY;

    try {
      const previous = window.sessionStorage.getItem(userKey);
      if (previous && previous !== user.id) {
        // The vendor widget's session is per SITE+WIDGET, not per app user.
        // Never let a second employee inherit the previous one's session.
        window.sessionStorage.removeItem(conversationKey);
      }
      window.sessionStorage.setItem(userKey, user.id);
    } catch {
      // Session storage can be blocked in private browsing.
    }
    lastUserId.current = user.id;

    const syncWidget = () => {
      const overlay = document.querySelector<HTMLElement>('[data-support-ai-root]');
      const shadow = overlay?.shadowRoot;
      if (!overlay || !shadow) return;
      overlay.style.pointerEvents = 'none';
      overlay.style.bottom = window.innerWidth < 768 ? '88px' : '14px';
      const toggle = shadow.querySelector<HTMLButtonElement>('.toggle');
      const panel = shadow.querySelector<HTMLElement>('.panel');
      if (toggle) {
        toggle.style.setProperty('display', 'none', 'important');
        toggle.style.setProperty('pointer-events', 'none', 'important');
        if (!shadow.querySelector('[data-johna-hide-launcher]')) {
          const style = document.createElement('style');
          style.dataset.johnaHideLauncher = '1';
          style.textContent = '.toggle { display: none !important; }';
          shadow.appendChild(style);
        }
      }
      if (!panel) return;
      panel.style.pointerEvents = 'auto';
      const header = shadow.querySelector<HTMLElement>('.head');
      if (header && !shadow.querySelector('[data-johna-close-chat]')) {
        header.style.display = 'flex';
        header.style.alignItems = 'center';
        header.style.justifyContent = 'space-between';
        const close = document.createElement('button');
        close.type = 'button';
        close.dataset.johnaCloseChat = '1';
        close.setAttribute('aria-label', 'إغلاق خدمة العملاء');
        close.textContent = '×';
        close.style.cssText = 'color:white;background:transparent;border:0;cursor:pointer;font-size:25px;line-height:1;padding:0 8px';
        close.addEventListener('click', () => {
          if (panel.classList.contains('open')) toggle?.click();
        });
        header.appendChild(close);
      }
    };
    const script = document.createElement('script');
    script.async = true;
    script.src = SUPPORT_ORIGIN + '/support/widget.js';
    script.dataset.widgetKey = PUBLIC_KEY;
    script.dataset.johnaSupport = '1';
    script.addEventListener('load', syncWidget);
    document.body.appendChild(script);
    const observer = new MutationObserver(syncWidget);
    observer.observe(document.body, { childList: true });
    window.addEventListener('resize', syncWidget);
    syncWidget();

    return () => {
      observer.disconnect();
      window.removeEventListener('resize', syncWidget);
      script.removeEventListener('load', syncWidget);
      script.remove();
      document.querySelectorAll('[data-support-ai-root]').forEach(root => root.remove());
    };
  }, [loading, user?.id]);

  // Remove chat UI when the employee signs out, but don't erase prior
  // messages merely because a page is being refreshed while auth hydrates.
  useEffect(() => {
    if (loading || user?.id || !lastUserId.current) return;
    document.querySelectorAll('[data-support-ai-root]').forEach(root => root.remove());
    document.querySelectorAll('script[data-johna-support]').forEach(script => script.remove());
    lastUserId.current = null;
  }, [loading, user?.id]);

  return null;
}
